<?php $labels=['slip_check'=>'สถานะตรวจสลิป','verification_note'=>'รายละเอียดตรวจสลิป','payment_token'=>'Payment token','token_revoked_at'=>'ยกเลิก token เมื่อ','slug'=>'ลิงก์บทความ','published_at'=>'เผยแพร่เมื่อ','id'=>'ID','sku'=>'SKU','name'=>'ชื่อ','email'=>'อีเมล','role'=>'สิทธิ์','active'=>'ใช้งาน','phone'=>'โทรศัพท์','referral_code'=>'Affiliate ID','sponsor_id'=>'ผู้แนะนำ ID','sponsor'=>'ผู้แนะนำ','link_clicks'=>'คลิกลิงก์','direct_members'=>'สมาชิกแนะนำตรง','referred_orders'=>'คำสั่งซื้อจากผู้แนะนำ','created_at'=>'สร้างเมื่อ','updated_at'=>'อัปเดตเมื่อ','price_satang'=>'ราคา','discount'=>'ส่วนลดสินค้า','total_satang'=>'ยอดสุทธิ','amount_satang'=>'ยอดชำระ','lifetime_satang'=>'ยอดสะสม','orders_count'=>'คำสั่งซื้อ','stock'=>'สต็อก','category'=>'หมวดหมู่','number'=>'เลขคำสั่งซื้อ','status'=>'สถานะ','reference'=>'อ้างอิง','review_note'=>'ผลตรวจ','code'=>'โค้ด','kind'=>'ประเภท','value'=>'มูลค่า (สตางค์ / bps)','minimum_satang'=>'ขั้นต่ำ','starts_at'=>'เริ่ม','ends_at'=>'สิ้นสุด','usage_limit'=>'จำนวนสิทธิ์','used'=>'ใช้แล้ว','contact'=>'ติดต่อ','source'=>'แหล่งที่มา','stage'=>'ขั้นตอน','score'=>'คะแนน','owner'=>'ผู้รับผิดชอบ','owner_id'=>'ผู้รับผิดชอบ ID','consent_at'=>'ยินยอมเมื่อ','notes'=>'บันทึก','title'=>'หัวข้อ','due_at'=>'กำหนด','lead_id'=>'Lead ID','platform'=>'ช่องทาง','external_id'=>'รหัสผู้สนทนา','mode'=>'โหมด','lead'=>'Lead','action'=>'การทำรายการ','actor'=>'ผู้ทำ','entity'=>'ประเภท','entity_id'=>'รายการ ID','detail'=>'รายละเอียด','quantity'=>'จำนวน','order_id'=>'คำสั่งซื้อ ID','product_id'=>'สินค้า ID','path'=>'หน้าเว็บ','pageviews'=>'การเข้าชม','visitors'=>'ผู้เข้าชม','referrer'=>'เว็บไซต์ต้นทาง','views'=>'การเข้าชม','note'=>'บันทึก','message_id'=>'ข้อความ ID','conversation_id'=>'บทสนทนา ID','attempts'=>'จำนวนครั้ง','error'=>'รายละเอียด']; ?>
<?php if(!$rows): ?><div class="empty">ยังไม่มีข้อมูลในส่วนนี้</div><?php else: ?><div class="table-scroll"><table><thead><tr><?php foreach(array_keys($rows[0]) as $key): ?><th data-column="<?= esc($key,'attr') ?>"><?= esc($labels[$key]??$key) ?></th><?php endforeach ?><?php if($module&&$module!=='analytics'): ?><th data-column="actions">จัดการ</th><?php endif ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($row as $key=>$value): ?><td data-column="<?= esc($key,'attr') ?>"><?php if(str_ends_with($key,'_satang')): ?><?= p_money($value) ?><?php elseif(str_ends_with($key,'_at')&&$value): ?><?= p_date($value) ?><?php elseif(in_array($key,['status','stage','role','mode'])): ?><span class="badge <?= esc($value,'attr') ?>"><?= esc(p_label($value)) ?></span><?php elseif($key==='referral_code'): ?><a href="<?= site_url('r/'.$value) ?>" target="_blank" rel="noopener"><strong><?= esc($value) ?></strong> ↗</a><?php elseif($key==='active'): ?><?= $value?'เปิด':'ปิด' ?><?php else: ?><?= esc(mb_strimwidth((string)($value??'—'),0,180,'…')) ?><?php endif ?></td><?php endforeach ?>
<?php if($module&&$module!=='analytics'): ?><td class="nowrap"><?php if(in_array($module,['blog','products','users','promotions','leads','tasks','orders','conversations'])): ?><a class="button secondary small" href="<?= site_url('admin/'.$module).'?edit='.$row['id'] ?>">เปิด / แก้ไข</a><?php if($module==='blog'): ?><?php if($row['status']==='published'): ?><a class="button secondary small" href="<?= site_url('blog/'.$row['slug']) ?>" target="_blank" rel="noopener">เปิดบทความ ↗</a><?php endif ?><?php if($row['status']!=='archived'): ?><form method="post" action="<?= site_url('admin/blog/archive/'.$row['id']) ?>"><?= csrf_field() ?><button class="small secondary">เก็บเข้าคลัง / ซ่อน</button></form><?php endif ?><?php endif ?><?php elseif($module==='payments'): ?><?php if(!str_starts_with($row['reference'],'stripe:')&&!str_starts_with($row['reference'],'opn:')): ?><a href="<?= site_url('admin/payments/slip/'.$row['id']) ?>" target="_blank" rel="noopener">เปิดสลิป ↗</a><?php endif ?><?php if($row['status']==='pending'): ?><form class="stack" method="post" action="<?= site_url('admin/payments/approve/'.$row['id']) ?>" style="margin-top:10px"><?= csrf_field() ?><input name="note" required minlength="3" maxlength="1000" placeholder="ผลตรวจรายการธนาคาร"><button class="small">อนุมัติ</button><button class="small danger" formaction="<?= site_url('admin/payments/reject/'.$row['id']) ?>">ไม่ผ่าน</button></form><?php endif ?><?php elseif($module==='affiliates'): ?><a class="button secondary small" href="<?= site_url('admin/affiliates').'?edit='.$row['id'] ?>">ดูสายงาน / โปรไฟล์</a><a class="button secondary small" href="<?= site_url('p/'.$row['referral_code']) ?>" target="_blank" rel="noopener">หน้าโปรโมท ↗</a><input aria-label="ลิงก์แนะนำ" class="copy-link" readonly value="<?= esc(site_url('r/'.$row['referral_code']),'attr') ?>" onclick="this.select()"><?php else: ?>—<?php endif ?></td><?php endif ?></tr><?php endforeach ?></tbody></table></div><?php endif ?>
